<include file="Public:header"/>	<form id="myform" method="post" action="{pigcms{:U('position_audit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="position_id" value="{pigcms{$detail.position_id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">企业名称</th>				<td width="35%">{pigcms{$detail.company_name}</td>			</tr>			<tr>				<th width="15%">职位名称</th>				<td width="35%">{pigcms{$detail.position_name}</td>			</tr>			<tr>				<th width="15%">学历</th>				<td width="35%">{pigcms{$detail.qualifications}</td>			</tr>			<tr>				<th width="15%">工作年限</th>				<td width="35%">{pigcms{$detail.work_years}</td>			</tr>			<tr>				<th width="15%">薪资待遇</th>				<td width="35%">{pigcms{$detail.salary}</td>			</tr>			<tr>				<th width="15%">福利待遇</th>				<td width="35%">{pigcms{$detail.welfare}</td>			</tr>			<tr>				<th width="15%">描述</th>				<td width="35%">{pigcms{$detail.desc}</td>			</tr>			<tr>				<th width="15%">地址</th>				<td width="35%">{pigcms{$detail.address}</td>			</tr>			<tr>				<th width="15%">状态</th>				<td width="35%">                         <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 eq $detail['status']">checked="checked"</if> value="1"/> 通过</label>                        <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 neq $detail['status']">checked="checked"</if> value="2" /> 不通过</label>                </td>			</tr>				<tr class="reason">				<th width="15%">原因</th>				<td width="35%">                   <input type="text" class="input fl" name="reason" value="{pigcms{$detail.reason}" placeholder="审核原因"/>                </td>			</tr>					</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form>	<script type="text/javascript">		$('input[name=status]').click(function (argument) {			if ($(this).val()==2) {				$('.reason').show();			}else{				$('.reason').hide();			}		})		$('input[name=status]').trigger('click');	</script><include file="Public:footer"/>